<script setup>import{onMounted,ref}from'vue';import{api}from'../../api/http.js';import{sessionStore}from'../../stores/session.js';import PageHeader from'../../components/common/PageHeader.vue';import T from'../../components/common/WorkspaceTable.vue';const rows=ref([]),employees=ref([]),error=ref(''),form=ref({employee_id:'',log_date:new Date().toISOString().slice(0,10),status:'Present',time_in:'',time_out:'',notes:''});async function load(){try{error.value='';const[d,e]=await Promise.all([api.attendance(),api.employees({per_page:100})]);rows.value=d.data;employees.value=e.data}catch(x){error.value=x.message}}async function save(){try{error.value='';await api.post('/attendance',form.value);await load()}catch(x){error.value=x.message}}onMounted(load)</script><template><PageHeader title="Attendance" description="Record and review employee time entries."/><p v-if="error" class="form-error">{{error}}</p><form v-if="sessionStore.can('hr.attendance.edit')" class="inline-form" @submit.prevent="save"><select v-model="form.employee_id" required><option value="">Employee</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.full_name}}</option></select><input v-model="form.log_date" type="date" required><select v-model="form.status"><option>Present</option><option>Late</option><option>Absent</option><option>On Leave</option></select><input v-model="form.time_in" type="time"><input v-model="form.time_out" type="time"><button class="primary-button">Save entry</button></form><T :columns="[{key:'log_date',label:'Date'},{key:'employee_no',label:'No.'},{key:'full_name',label:'Employee'},{key:'status',label:'Status'},{key:'time_in',label:'In'},{key:'time_out',label:'Out'}]" :rows="rows"/></template>
